import { AppContext } from "../../context/AppContext";
import { useContext, useEffect } from "react";
import { fetchBudget } from "../utils/budget-utils"; // import fetchBudget function

const Budget = () => {
  const { budget, setBudget } = useContext(AppContext); // ensure setBudget is available

  useEffect(() => {
    const loadBudget = async () => {
      const fetchedBudget = await fetchBudget();
      setBudget(fetchedBudget); // update context budget
    };
    loadBudget();
  }, []);

  return (
    <div className="alert alert-secondary p-3 d-flex align-items-center justify-content-between">
      <div>Budget: ${budget}</div>
    </div>
  );
};

export default Budget;
